function output = heartlib(T, P, M)
% output = heartlib(T, P, M)
%
%    A = <T , P>_M
%                        where 
%                        T: ℝ ^ 2: a sequence
%                        P: ℝ ^ 2: a sequence 
%                        M: ℝ ^ (2×2): a sequence
    T = reshape(T,[],1);
    P = reshape(P,[],1);

    assert( numel(T) == 2 );
    assert( numel(P) == 2 );
    assert( isequal(size(M), [2, 2]) );

    % A = <T , P>_M

    A = (P)' * (M) * (T);
    output.A = A;
end

